operation.add:
$data['product_storefront_name'] = '';
$data['product_storefront_href'] = '';

if (!empty($product_info)) {
	$this->load->model('localisation/language');

	$storefront_language = $this->model_localisation_language->getLanguageByCode($this->config->get('config_language'));
	$storefront_language_id = $storefront_language ? (int)$storefront_language['language_id'] : (int)$this->config->get('config_language_id');
	$storefront_base = defined('HTTPS_CATALOG') && HTTPS_CATALOG ? HTTPS_CATALOG : HTTP_CATALOG;

	if ($this->config->get('config_seo_url') && !empty($data['product_seo_url'][0][$storefront_language_id])) {
		$data['product_storefront_href'] = $storefront_base . $data['product_seo_url'][0][$storefront_language_id];
	} else {
		$data['product_storefront_href'] = $storefront_base . 'index.php?route=product/product&product_id=' . (int)$product_info['product_id'];
	}

	$data['product_storefront_name'] = $product_info['name'];
}

{% if product_storefront_href %}
        <h3 class="panel-title"><i class="fa fa-pencil"></i> <a href="{{ product_storefront_href }}" target="_blank" rel="noopener">{{ product_storefront_name }} <i class="fa fa-external-link"></i></a></h3>
        {% else %}
        <h3 class="panel-title"><i class="fa fa-pencil"></i> {{ text_form }}</h3>
        {% endif %}
